const { LRUCache } = require('./src/lru');
const assert = require('assert/strict');
for (const c of [0, -1, 1.5, Infinity, NaN, '3', undefined]) {
  assert.throws(() => new LRUCache(c), RangeError);
}
// undefined value still refreshes recency
const c = new LRUCache(2);
c.set('a', undefined).set('b', 2);
assert.equal(c.get('a'), undefined); // refreshes 'a'
c.set('c', 3);
assert.equal(c.has('a'), true);
assert.equal(c.has('b'), false);
// updating existing entry does not evict unrelated entry or grow size
const d = new LRUCache(2);
d.set('a', 1).set('b', 2);
d.set('a', 99);
assert.equal(d.size, 2);
assert.equal(d.has('b'), true);
assert.equal(d.get('a'), 99);
// arbitrary keys, independent caches
const k = {};
const e = new LRUCache(1);
e.set(k, 'obj');
assert.equal(e.get(k), 'obj');
assert.equal(d.has(k), false);
console.log('all edge cases OK');
"
